func TestCompletionBudgetRecoveryProjectionParity(t *testing.T) {
	type backend struct {
		name  string
		start func(*testing.T) (budgetRecoveryParityStore, *sql.DB, bool)
	}
	backends := []backend{{name: "sqlite", start: func(t *testing.T) (budgetRecoveryParityStore, *sql.DB, bool) {
		s := storetest.StartSQLiteRuntimeStore(t)
		return s, storetest.Database(s), false
	}}, {name: "postgres", start: func(t *testing.T) (budgetRecoveryParityStore, *sql.DB, bool) {
		_, db, cleanup := testutil.StartPostgres(t)
		t.Cleanup(cleanup)
		return storetest.AdmitPostgresRuntimeStore(t, db), db, true
	}}}
	for _, tc := range backends {
		t.Run(tc.name, func(t *testing.T) {
			selected, db, postgres := tc.start(t)
			ctx := testAuthorActivityContext(context.Background())
			now := time.Now().UTC().Truncate(time.Second)
			runA, runB := uuid.NewString(), uuid.NewString()
			entityA, entityB, terminalEntity, crossSourceEntity := uuid.NewString(), uuid.NewString(), uuid.NewString(), uuid.NewString()
			otherArtifact := sourceartifactfixture.New("agents.yaml", []byte("agents: {}\n# budget-stage-second-source\n"))
			seedBudgetRecoveryRun(t, ctx, selected, runA, now)
			storetest.RequireRun(t, ctx, selected, storetest.RunFixture{Origin: storetest.ScenarioSetupOrigin(), RunID: runB, Artifact: otherArtifact, StartedAt: now.Add(time.Second)})
			seedBudgetRecoveryEntity(t, ctx, db, postgres, runA, entityA, "active", now)
			seedBudgetRecoveryEntity(t, ctx, db, postgres, runB, entityB, "active", now.Add(time.Second))
			seedBudgetRecoveryEntity(t, ctx, db, postgres, runA, terminalEntity, "done", now.Add(2*time.Second))
			seedBudgetRecoveryEntity(t, ctx, db, postgres, runB, crossSourceEntity, "done", now.Add(3*time.Second))
			for _, seed := range []struct {
				runID  string
				record budgetspend.SpendRecord
			}{{runID: runA, record: budgetRecoverySpend(t, entityA, "flow/a", 9.5, now)}, {runID: runB, record: budgetRecoverySpend(t, entityB, "flow/b", 9.5, now)}, {runID: runA, record: budgetRecoverySpend(t, terminalEntity, "flow/done", 9.5, now)}, {runID: runB, record: budgetRecoverySpend(t, crossSourceEntity, "flow/cross-source", 9.5, now)}, {record: budgetRecoverySpend(t, "", "global", 9.5, now)}} {
				spendCtx := ctx
				if seed.runID != "" {
					spendCtx = runtimecorrelation.WithRunID(spendCtx, seed.runID)
					if seed.runID == runB {
						spendCtx = runtimecorrelation.WithSourceArtifactFact(spendCtx, sourceartifactfixture.FactFor(otherArtifact))
						spendCtx = runtimeauthoractivity.WithScope(spendCtx, runtimeauthoractivity.BundleScope(authorActivityTestRuntimeInstanceID, otherArtifact.BundleHash()))
					}
				}
				if err := selected.RecordSpend(spendCtx, seed.record); err != nil {
					t.Fatalf("seed retained spend: %v", err)
				}
			}
			bus, err := newRuntimeTestEventBus(t, selected)
			if err != nil {
				t.Fatalf("NewEventBus: %v", err)
			}
			source := semanticview.Wrap(&runtimecontracts.WorkflowContractBundle{SourceArtifact: authorActivityTestSourceArtifact, RootSchema: &runtimecontracts.FlowSchemaDocument{StageDeclarations: runtimecontracts.FlowStageDeclarations{Declared: true, Entries: []runtimecontracts.FlowStageDeclaration{{ID: "active"}, {ID: "done", Final: true}}}}, FlowSchemas: map[string]runtimecontracts.FlowSchemaDocument{"flow": {}}, Semantics: runtimecontracts.WorkflowSemanticView{StageTopologies: map[string]runtimecontracts.WorkflowStageTopology{".": runtimecontracts.BuildWorkflowStageTopology(".", "active", []string{"active", "done"}, []string{"done"}, nil, nil, nil), "flow": runtimecontracts.BuildWorkflowStageTopology("flow", "active", []string{"active", "done"}, []string{"done"}, nil, nil, nil)}}, Policy: runtimecontracts.PolicyDocument{Values: map[string]runtimecontracts.PolicyValue{"budget_warning_percent": {Value: 50}, "budget_throttle_percent": {Value: 75}, "budget_emergency_percent": {Value: 90}}}})
			otherSource := semanticview.Wrap(&runtimecontracts.WorkflowContractBundle{SourceArtifact: otherArtifact, FlowSchemas: map[string]runtimecontracts.FlowSchemaDocument{"flow": {}}, Semantics: runtimecontracts.WorkflowSemanticView{Version: otherArtifact.BundleHash(), StageTopologies: map[string]runtimecontracts.WorkflowStageTopology{".": runtimecontracts.BuildWorkflowStageTopology(".", "active", []string{"active", "done"}, []string{"done"}, nil, nil, nil), "flow": runtimecontracts.BuildWorkflowStageTopology("flow", "active", []string{"active", "done", "closed"}, []string{"closed"}, nil, nil, nil)}}})
			loads := 0
			tracker := runtimepkg.NewBudgetTracker(selected, bus, &config.Config{Extensions: map[string]any{"budget": map[string]any{"system_monthly_cap": 40, "global_monthly_cap": 10, "per_entity_monthly_cap": 10}}}, selected, nil, source, executionposture.Live, runtimepkg.BudgetRecoveryStageSources{CurrentBundleHash: authorActivityTestSourceArtifactFact.BundleHash(), Load: func(ctx context.Context, hash string) (semanticview.Source, error) {
				loads++
				persisted, err := selected.GetSourceArtifact(ctx, hash)
				if err != nil {
					return nil, err
				}
				decoded, err := persisted.Decode()
				if err != nil || decoded.BundleHash() != otherArtifact.BundleHash() {
					return nil, fmt.Errorf("budget recovery selected source mismatch: decoded=%v err=%v", decoded, err)
				}
				return otherSource, nil
			}})
			coordinate := runtimeagenttopology.SourceCoordinate{BundleHash: authorActivityTestSourceArtifactFact.BundleHash()}
			plan, err := runtimeagenttopology.NewSourceSetPlan([]runtimeagenttopology.SourceCoordinate{coordinate}, nil)
			if err != nil {
				t.Fatalf("construct budget recovery topology plan: %v", err)
			}
			capability, err := selected.AcquireProcessCapability(ctx, runtimestartupownership.AcquireRequest{OwnerID: "budget-recovery-test", BootID: uuid.NewString(), RuntimeInstanceID: authorActivityTestRuntimeInstanceID})
			if err != nil {
				t.Fatalf("acquire budget recovery process capability: %v", err)
			}
			if _, err := capability.InstallCompleteSourceSet(ctx, runtimeagenttopology.SourceSetCommitRequest{OperationID: uuid.NewString(), Plan: plan}); err != nil {
				t.Fatalf("install budget recovery source set: %v", err)
			}
			grant, err := capability.IssueGenerationGrant(ctx, runtimestartupownership.GrantRequest{BundleHash: coordinate.BundleHash, RuntimeInstanceID: authorActivityTestRuntimeInstanceID, RuntimeGeneration: 1, SourceSetRevision: plan.Revision})
			if err != nil {
				t.Fatalf("issue budget recovery generation grant: %v", err)
			}
			manager := runtimemanager.NewAgentManagerWithOptions(bus, nil, runtimemanager.AgentManagerOptions{BaseContext: ctx, LifecycleStore: grant, SemanticSource: source, Budget: tracker, WorkOwner: runtimeTestEventBusWorkOwner(t, bus), ReceiverExecution: eventreceiver.NormalExecution()}, selected)
			topologyAdmission, err := runtimeagenttopology.StaticAdmission(plan.Revision, coordinate.BundleHash, runtimeagenttopology.LifetimeDurableManaged)
			if err != nil {
				t.Fatalf("construct budget recovery topology admission: %v", err)
			}
			if err := manager.InstallStartupTopology(grant, topologyAdmission, plan); err != nil {
				t.Fatalf("install budget recovery manager topology: %v", err)
			}
			if err := manager.ReconcileStaticTopologyForStartup(ctx, source); err != nil {
				t.Fatalf("reconcile budget recovery manager topology: %v", err)
			}
			t.Cleanup(func() {
				if err := closeExternalManagerTestGeneration(manager, bus, grant, capability); err != nil {
					t.Errorf("close budget recovery generation: %v", err)
				}
			})
			admission, err := managedexecution.New(managedexecution.KindNormalRuntime, "budget-recovery-test", 1, "", "budget-recovery-actors", "bundle-v2:sha256:eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee", nil)
			if err != nil {
				t.Fatalf("managedexecution.New: %v", err)
			}
			managedCtx := managedexecution.WithAdmission(ctx, admission)
			if _, err := manager.RecoverWithStartupReplayDiagnostics(managedCtx); err != nil {
				t.Fatalf("RecoverWithStartupReplayDiagnostics with process context: %v", err)
			}
			assertRecoveredBudgetState(t, tracker, entityA, entityB, terminalEntity, crossSourceEntity)
			if loads != 1 {
				t.Fatalf("selected source loads = %d, want one per recovery pass", loads)
			}
			assertBudgetRecoverySideEffects(t, ctx, db, 5, 5)
			if _, err := manager.RecoverWithStartupReplayDiagnostics(managedCtx); err != nil {
				t.Fatalf("repeated RecoverWithStartupReplayDiagnostics with process context: %v", err)
			}
			assertRecoveredBudgetState(t, tracker, entityA, entityB, terminalEntity, crossSourceEntity)
			if loads != 2 {
				t.Fatalf("selected source loads after repeated recovery = %d, want one per pass", loads)
			}
			assertBudgetRecoverySideEffects(t, ctx, db, 5, 5)
		})
	}
}

