	_, db, _ := testutil.StartPostgres(t)
	pg := storetest.AdmitPostgresRuntimeStore(t, db)
	source := semanticview.Wrap(runStartTestBundle("scan.requested"))
	started := make(chan struct{}, 1)
	release := make(chan struct{})
