			var raw map[string]any
			if err := json.Unmarshal(original.Payload(), &raw); err != nil {
				t.Fatal(err)
			}
			if _, invented := raw["operating_id"]; invented {
				t.Fatalf("connection projection mutated source business payload: %#v", raw)
			}
