		r := nested[parent.ID]
		if r.LoadedAt.Before(parentReturned) || r.Publications != 2 || r.Key == held.Key {
			t.Fatalf("nested intent requires independent post-parent turn: parent=%+v nested=%+v", held, r)
		}
