			query string
			value *int
		}{{`SELECT COUNT(*) FROM events WHERE run_id=$1 AND event_name='portfolio/account.registered'`, &events}, {`SELECT COUNT(*) FROM event_deliveries WHERE run_id=$1`, &deliveries}, {`SELECT COUNT(*) FROM event_receipts r JOIN events e ON e.event_id=r.event_id WHERE e.run_id=$1 AND r.subscriber_type='platform' AND r.subscriber_id='pipeline'`, &receipts}, {`SELECT COUNT(*) FROM decision_card_route_obligations r JOIN events e ON e.event_id=r.event_id WHERE e.run_id=$1`, &routes}} {
			if err := f.db.QueryRowContext(ctx, check.query, runID).Scan(check.value); err != nil {
				t.Fatal(err)
			}
		}
		statusRows, err := f.db.QueryContext(ctx, `SELECT status, COUNT(*) FROM event_deliveries WHERE run_id=$1 GROUP BY status ORDER BY status`, runID)
		if err != nil {
			t.Fatal(err)
		}
		var deliveryStatuses []string
		for statusRows.Next() {
			var status string
			var count int
			if err := statusRows.Scan(&status, &count); err != nil {
				statusRows.Close()
				t.Fatal(err)
			}
			deliveryStatuses = append(deliveryStatuses, fmt.Sprintf("%s=%d", status, count))
		}
		if err := statusRows.Err(); err != nil {
			statusRows.Close()
			t.Fatal(err)
		}
		statusRows.Close()
		t.Fatalf("deployment source did not settle through real receivers: intents=%d committed=%d events=%d deliveries=%d delivery_statuses=%v pipeline_receipts=%d routes=%d children=%d delivered=%d want=%d", intents, committed, events, deliveries, deliveryStatuses, receipts, routes, children, delivered, len(compiled.Rows))
