	handler, err := apiv1.NewHandler(apiv1.Options{PlatformSpecPath: filepath.Join(conformanceRepoRoot(t), "platform-spec.yaml"), AuthTokens: []string{token}, Handlers: apiv1.OperatorObservabilityHandlers(apiv1.ObservabilityHandlerOptions{Observability: reader})})
