			return nil
		}
		changed := c.changed
		c.mu.Unlock()
		if c.reservationGate != nil {
			c.reservationGate.afterAttempt(ctx, *timing, false, available)
		}
		select {
		case <-changed:
		case <-ctx.Done():
			return ctx.Err()
		}
	}
