	script := `#!/bin/sh
state="$SWARM_FAKE_DOCKER_STATE"
count=0
if [ -f "$state" ]; then
  count=$(cat "$state")
fi
count=$((count + 1))
printf "%s" "$count" > "$state"
if [ "$count" -eq 1 ]; then
  printf "session not found" >&2
  exit 1
fi
printf '{"result":"ok"}'
`
	if err := os.WriteFile(fakeDocker, []byte(script), 0o755); err != nil {
