		base = agentmemory.WithExecution(base, agentmemory.Plan{Enabled: true}, lifecycleToken.Identity)
		base = runtimecorrelation.WithRunID(base, runID)
		base = runtimebus.WithInboundEvent(base, evt)
		if deliveryClaim.DeliveryID() != "" {
			base = runtimedelivery.WithClaim(base, deliveryClaim)
		}
		return runtimeactors.WithActor(base, runtimeactors.AgentConfig{ExecutionMode: "live", ID: "agent-1", Identity: lifecycleToken.Identity, Type: "stub", Memory: agentmemory.Plan{Enabled: true}, FlowPath: "support/inst-1"})
