			if err := runtime.manager.Run(managedConformanceExecutionContextForBundle(t, ctx, "fan-out-delivery-barrier", runtime.sourceArtifactFact)); err != nil {
				t.Fatalf("run manager: %v", err)
			}
			publishNotifyAllChildrenRunCreatingEvent(t, ctx, runtime, source, runID, "portfolio.opened", map[string]any{"portfolio_id": "portfolio-main"})
			accountIDs := []string{"acct-c", "acct-a", "acct-b"}
			publishNotifyAllChildrenEvent(t, ctx, runtime, source, runID, "portfolio.accounts.register.requested", map[string]any{"portfolio_id": "portfolio-main", "account_ids": accountIDs})
			notifyID := publishNotifyAllChildrenEventAsync(t, ctx, runtime, source, runID, "portfolio.notify.requested", map[string]any{"portfolio_id": "portfolio-main", "command": "barrier-proof"})
			waitNotifyAllChildrenRuntime(t, runtime, runID)
			items := loadNotifyAllChildrenItemEvents(t, ctx, selected, runID, notifyID)
			if len(items) != len(accountIDs) {
				t.Fatalf("fan-out item events = %#v, want %d", items, len(accountIDs))
			}
			operatorStore, ok := selected.(interface {
				LoadOperatorEvent(context.Context, string) (operatorread.OperatorEventFull, error)
			})
			if !ok {
				t.Fatalf("notify-all-children store %T lacks operator event readback", selected)
			}
			for _, item := range items {
				view, err := operatorStore.LoadOperatorEvent(ctx, item.ID)
