			failureOwner := workflowTimerStartupTopologyFailureOwner{WorkflowPersistenceOwner: selected, readiness: runtimepipeline.DynamicFlowRuntimeReadiness{InstancePath: "review/inst-1", OwningRunSource: sourceFact, RunStatus: "running", InstanceStatus: "active", Plan: runtimepipeline.DynamicFlowRuntimeReadinessPlan{RunID: workflowRunID, BundleHash: bundleHash, WorkflowVersion: source.WorkflowVersion() + "-stale", ExecutionMode: executionmode.Live, Identity: runtimeflowidentity.Instance{TemplateID: "review", ScopeKey: "review", InstanceID: "inst-1", InstancePath: "review/inst-1", EntityID: uuid.NewString(), HasStoredPath: true}}}}
			failedRuntime, failedProcess := newRuntime(failureOwner)
			failedCapability, _ := installExternalRuntimeTestGeneration(t, ctx, selected, failedRuntime)
			err = failedRuntime.Start(ctx)
			if err == nil || !strings.Contains(err.Error(), "workflow version changed") {
