	t.Run("postgres", func(t *testing.T) {
		const flowInstance = boundedProviderFlowID
		runID, entityID := boundedInboundTestCoordinates()
		ctx := testAuthorActivityContext(runtimecorrelation.WithRunID(testAuthorActivityContext(context.Background()), runID))
		pg := storetest.StartPostgresRuntimeStore(t)
		target := seedPostgresInboundGatewayRuntime(t, ctx, pg, runID, entityID, flowInstance, "customer-a", "telegram", "telegram-secret", "telegram-supported-surface-observer")
		runTelegramConnectorSupportedSurfaceRoundTrip(t, telegramConnectorSupportedSurfaceBackend{name: "postgres", ctx: ctx, eventStore: pg, deliveryStore: pg, inboundStore: pg, inboundTarget: target, persistence: runtimepipeline.NewWorkflowPersistence(pg), runLifecycle: pg, obligations: pg.PipelineObligations(), runID: runID, entityID: entityID, flowInstance: flowInstance})
	})
	t.Run("sqlite", func(t *testing.T) {
		const flowInstance = boundedProviderFlowID
		runID, entityID := boundedInboundTestCoordinates()
		ctx := testAuthorActivityContext(runtimecorrelation.WithRunID(testAuthorActivityContext(context.Background()), runID))
		sqliteStore := storetest.StartSQLiteRuntimeStoreWithContext(t, ctx)
		target := seedSQLiteInboundGatewayRuntime(t, ctx, sqliteStore, runID, entityID, flowInstance, "customer-a", "telegram", "telegram-secret", "telegram-supported-surface-observer")
		runTelegramConnectorSupportedSurfaceRoundTrip(t, telegramConnectorSupportedSurfaceBackend{name: "sqlite", ctx: ctx, eventStore: sqliteStore, deliveryStore: sqliteStore, inboundStore: sqliteStore, inboundTarget: target, persistence: runtimepipeline.NewWorkflowPersistence(sqliteStore), runLifecycle: sqliteStore, obligations: sqliteStore.PipelineObligations(), runID: runID, entityID: entityID, flowInstance: flowInstance})
	})
}

