				}
				if scenario.descendant != "" {
					assertA2ConstructedGateSources(t, ctx, selected, plan)
				}
				if arm := exactJoinPersistedArmForOwner(t, persisted, owner); !reflect.DeepEqual(arm, plannedArm) {
