		t.Fatalf("durable progress: intents=%d outcomes=%d events=%d cursor=%d cardinality=%d status=%s mutation=%s; want %d/%d/%s/%s", len(evidence.Intents), evidence.Outcomes, eventsCount, intent.Cursor, intent.Cardinality, intent.Status, intent.SourceMutationID, cursor, cardinality, status, sourceMutation)
