			bound := 0
			for _, route := range prepared.DeliveryRoutes {
				if route.Recipient.ID() == collector.Key() && len(route.Context.Joins) == 1 && route.Context.Joins[0].Disposition == events.JoinAdmissionBound && route.Context.Joins[0].Ref.Equal(arm.JoinRef()) {
					bound++
				}
			}
			if bound != 1 {
				t.Fatalf("ordinal %d lacks its exact stage-entry receipt: %#v", output.Ordinal, prepared.DeliveryRoutes)
			}
		}
