func TestEntityTools_SaveEntityFieldAfterForkActivationUsesForkRunID(t *testing.T) {
	actor := models.AgentConfig{ExecutionMode: "live", ID: "tester", Type: "internal", Role: "operator", Tools: []string{"get_entity", "save_entity_field"}}
	bundle := loadWave1EntityToolBundle(t, actor, "review", "accounts", "", `
accounts:
  status: text
`)
	pg := storetest.StartPostgresRuntimeStore(t)
	sourceRunID := uuid.NewString()
	entityID := uuid.NewString()
	stateEventID := uuid.NewString()
	forkEventID := uuid.NewString()
	at := time.Unix(1700000720, 0).UTC()
	forkAt := at.Add(30 * time.Second)
	bundleHash := bundle.SourceArtifact.BundleHash()
	fact, err := runtimecorrelation.NewSourceArtifactFact(bundleHash)
	if err != nil {
		t.Fatal(err)
	}
	ctx := runtimecorrelation.WithSourceArtifactFact(runtimecorrelation.WithRunID(unmanagedToolTestContext(), sourceRunID), fact)
	storetest.RequireRun(t, ctx, pg, storetest.RunFixture{Origin: storetest.ScenarioSetupOrigin(), RunID: sourceRunID, StartedAt: at.Add(-time.Minute), Artifact: bundle.SourceArtifact})
	storetest.InsertNativeCanonicalEventRecord(t, ctx, pg, eventtest.PersistedProjectionForProducer(stateEventID, "fork.state_entry", eventtest.Producer(events.EventProducerPlatform, "test"), "", []byte(`{}`), 0, sourceRunID, "", events.EventEnvelope{EntityID: entityID, Scope: events.EventScopeEntity}, at))
	source := semanticview.Wrap(bundle)
	pc := newEntityToolPipeline(t, pg, source)
	constructEntityToolFixture(t, ctx, pg, pc, source, "review", "review/inst-1", entityID, "queued", map[string]any{"status": "open"}, at)
	storetest.CaptureSelectedRunForkRevision(t, ctx, pg, sourceRunID, runforkrevision.AllFamilies()...)
	storetest.InsertNativeCanonicalEventRecord(t, ctx, pg, eventtest.PersistedProjectionForProducer(forkEventID, "fork.field_only", eventtest.Producer(events.EventProducerPlatform, "test"), "", []byte(`{}`), 0, sourceRunID, "", events.EventEnvelope{EntityID: entityID, Scope: events.EventScopeEntity}, forkAt))
	materialized, err := pg.MaterializeRunFork(ctx, runfork.RunForkMaterializeRequest{SourceRunID: sourceRunID, At: forkEventID})
	if err != nil {
		t.Fatalf("MaterializeRunFork: %v", err)
	}
	activated, err := pg.ActivateRunFork(ctx, runfork.RunForkActivateRequest{ForkRunID: materialized.ForkRunID, AllowSourceFreeze: true})
	if err != nil {
		t.Fatalf("ActivateRunFork: %v", err)
	}
	if !activated.Activated || !activated.SourceFrozen {
		t.Fatalf("activation result = %#v", activated)
	}
	exec := runtimetools.NewExecutorWithOptions(nil, runtimetools.ExecutorOptions{EntityStore: pg, EntityWriter: pc, WorkflowSource: semanticview.Wrap(bundle), AllowInternalLegacyEntityTools: true})
	forkSource, err := runtimecorrelation.NewSourceArtifactFact(bundleHash)
	if err != nil {
		t.Fatalf("NewSourceArtifactFact: %v", err)
	}
	forkCtx := runtimecorrelation.WithRunID(unmanagedToolTestContext(), materialized.ForkRunID)
	forkCtx = runtimecorrelation.WithSourceArtifactFact(forkCtx, forkSource)
	actor = entityToolFixtureActor(t, semanticview.Wrap(bundle), actor, materialized.ForkRunID, "review", "review/inst-1")
	forkCtx = runtimetools.WithActor(forkCtx, actor)
	if _, err := exec.Execute(forkCtx, "save_entity_field", map[string]any{"entity_id": entityID, "field": "status", "value": "fork-active"}); err != nil {
		t.Fatalf("save_entity_field on activated fork: %v", err)
	}
	sourceStatus, err := storetest.ReadEntityToolStatus(ctx, pg, sourceRunID, entityID)
	if err != nil {
		t.Fatalf("load source entity_state: %v", err)
	}
	forkRow, err := storetest.ReadEntityToolStatusRevision(ctx, pg, materialized.ForkRunID, entityID)
	if err != nil {
		t.Fatalf("load fork entity_state: %v", err)
	}
	if sourceStatus != "open" || forkRow.Status != "fork-active" {
		t.Fatalf("source/fork status = %s/%s, want open/fork-active", sourceStatus, forkRow.Status)
	}
	if forkRow.Revision != 2 {
		t.Fatalf("fork revision = %d, want 2 after fork-local write", forkRow.Revision)
	}
	forkMutationCount, err := storetest.CountEntityToolAgentStatusMutations(ctx, pg, materialized.ForkRunID, entityID)
	if err != nil {
		t.Fatalf("count fork status mutation: %v", err)
	}
	sourceMutationCount, err := storetest.CountEntityToolAgentStatusMutations(ctx, pg, sourceRunID, entityID)
	if err != nil {
		t.Fatalf("count source status mutation: %v", err)
	}
	if forkMutationCount != 1 || sourceMutationCount != 0 {
		t.Fatalf("fork/source save_entity_field mutation count = %d/%d, want 1/0", forkMutationCount, sourceMutationCount)
	}
}

