				if err := db.QueryRow(`SELECT e.state,r.status FROM run_fork_selected_contract_runtime_executions e JOIN runs r ON r.run_id=e.fork_run_id WHERE r.run_id=$1`, checkpoint.ForkRun).Scan(&state, &status); err != nil {
					t.Fatal(err)
				}
