								t.Fatalf("workspace failure advanced source release: %v %v", err, probe.calls)
							}
						}
						func() {
							defer func() {
								if got := recover(); got != nil {
									if tc.phase != "panic" || got != errSourceRelease {
										panic(got)
									}
									err = p.closeErr
								}
							}()
							err = p.Close()
						}()
					}
