						go func() {
							retired <- owner.RetireSelectedContexts(context.Background())
						}()
						select {
						case err := <-retired:
							close(release)
							t.Fatalf("retirement skipped accepted execution/control disposition: %v", err)
						default:
						}
					}
					close(release)
					if err := <-finished; err == nil {
