	t.Helper()
	initial := requireServedEventPublishRPCResult(t, rt.Endpoint, map[string]any{"event_name": "external.observed", "bundle_hash": rt.BundleHash, "payload": map[string]any{}, "idempotency_key": "issue-1997-" + rt.Backend + "-source-run"})
	if !initial.NewRunCreated || initial.RunID == "" {
		t.Fatalf("%s conversation fork source run = %#v", rt.Backend, initial)
	}
	waitServedRunDeliveryQuiescence(t, rt.ReadRunDeliveries, initial.RunID)
	ready := requireServedEventPublishRPCResult(t, rt.Endpoint, map[string]any{"event_name": "fork.source_message", "run_id": initial.RunID, "source_event_id": initial.EventID, "payload": map[string]any{"note": "materialize source agent"}, "idempotency_key": "issue-1997-" + rt.Backend + "-source-agent-readiness"})
	if ready.RunID != initial.RunID || ready.NewRunCreated {
		t.Fatalf("%s conversation fork source-agent readiness = %#v", rt.Backend, ready)
	}
	waitServedConversationForkSourceAgentReady(t, rt, initial.RunID, ready.EventID)
	fixture := seedServedConversationForkSource(t, rt, initial.RunID)
	keyPrefix := "issue-1997-" + rt.Backend + "-" + fixture.SessionID
	create := func(selector map[string]any, key string) struct {
		Fork                runfork.OperatorConversationForkSession `json:"fork"`
		IdempotencyReplayed bool                                    `json:"idempotency_replayed"`
	} {
		params := map[string]any{"source_session_id": fixture.SessionID, "fork_point": selector}
		if key != "" {
			params["idempotency_key"] = key
		}
		var result struct {
			Fork                runfork.OperatorConversationForkSession `json:"fork"`
			IdempotencyReplayed bool                                    `json:"idempotency_replayed"`
		}
		requireServedJSONRPCResult(t, rt.Endpoint, "conversation.fork", params, &result)
		return result
	}
