			}
			published := requireServedEventPublishRPCResult(t, rt.Endpoint, map[string]any{"bundle_hash": rt.BundleHash, "run_id": run, "event_name": "widget.scored", "idempotency_key": uuid.NewString(), "payload": map[string]any{"delta": public.Fields["score"]}})
