							for _, query := range []string{`SELECT status,COALESCE(verdict,''),COALESCE(decided_by,''),COALESCE(CAST(decision_event_id AS TEXT),''),CAST(updated_at AS TEXT) FROM decision_cards WHERE card_id=$1`, `SELECT CAST(input_draft_id AS TEXT),CAST(principal_id AS TEXT),status,CAST(expires_at AS TEXT),CAST(updated_at AS TEXT) FROM decision_card_input_drafts WHERE card_id=$1 ORDER BY input_draft_id`, `SELECT CAST(change_id AS TEXT),change_type,CAST(payload AS TEXT),'','' FROM decision_card_changes WHERE card_id=$1 ORDER BY change_id`} {
