		if delivery.SubscriberType != "node" || delivery.SubscriberID != node.Key() || delivery.Status != "delivered" || delivery.Target.FlowInstance != path || delivery.Target.EntityID != entityID {
			t.Fatalf("direct input exact owner=%+v", delivery)
		}
		if eventID == autoEvent && (public.SourceEventID != seed.EventID || !reflect.DeepEqual(public.Payload, wantFields)) {
			t.Fatalf("initialization publication lost exact typed config/source: %+v", public)
		}
		var settled int
		if err := rt.DB.QueryRow(`SELECT COUNT(*) FROM event_deliveries d JOIN (SELECT delivery_id, claim_version, outcome, reason_code, failure, side_effects, duration_ms, completed_at AS settled_at FROM event_delivery_attempts WHERE closure_kind='settled') o ON o.delivery_id=d.delivery_id WHERE d.event_id=$1 AND d.claim_version=1 AND o.claim_version=1 AND o.outcome='delivered'`, eventID).Scan(&settled); err != nil {
			t.Fatal(err)
		}
		if settled != 1 {
			t.Fatalf("direct input first-claim outcomes=%d, want 1", settled)
		}
	}
	var count int
	if err := rt.DB.QueryRow(`SELECT COUNT(*) FROM events WHERE run_id=$1 AND event_name NOT LIKE 'platform.%'`, seed.RunID).Scan(&count); err != nil || count != 2 {
		t.Fatalf("direct input introduced an intermediate publication: count=%d err=%v", count, err)
	}
	deadline := time.Now().Add(servedProofPollDeadline)
	for {
		var settled bool
		if err := rt.DB.QueryRow(`SELECT completion_due_at IS NULL FROM runs WHERE run_id=$1`, seed.RunID).Scan(&settled); err != nil {
			t.Fatal(err)
		}
		if settled {
			break
		}
		if time.Now().After(deadline) {
			t.Fatal("direct input completion candidate did not settle")
		}
		time.Sleep(10 * time.Millisecond)
	}
	before := receiverIngressApplicationSnapshot(t, rt.ReceiverStateReader)
	duplicate := requireServedEventPublishRPCResult(t, rt.Endpoint, params)
	if duplicate.RunID != seed.RunID || duplicate.EventID != seed.EventID {
		t.Fatalf("duplicate direct input changed publication identity: first=%+v duplicate=%+v", seed, duplicate)
	}
	after := receiverIngressApplicationSnapshot(t, rt.ReceiverStateReader)
	for table, rows := range before {
		if !reflect.DeepEqual(rows, after[table]) {
			t.Fatalf("duplicate direct input changed %s: before=%v after=%v", table, rows, after[table])
		}
	}
}

