			if err := result.FanOut.Validate(); err != nil {
				t.Fatal(err)
			}
			if f.RunID != runID || f.BarrierArmed != 0 || f.BarrierPending != 0 {
				t.Fatalf("served diagnosis lost exact mixed outcomes: %+v", f)
