			t.Fatal(err)
		}
		if err := json.Unmarshal([]byte(oldJSON), &mutation.Old); err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal([]byte(newJSON), &mutation.New); err != nil {
			t.Fatal(err)
		}
