		return gotMutations[i].WriterID < gotMutations[j].WriterID
	})
	if !reflect.DeepEqual(gotMutations, wantMutations) {
		t.Fatalf("fresh acquisition marker history: got=%+v want=%+v", gotMutations, wantMutations)
