		var err error
		count, err = storetest.CountRunStateEntityStorage(ctx, reader, runID, state)
		return err
	})
	if err != nil {
		t.Fatal(err)
	}
	if count != want {
		t.Fatalf("run %s state %s count=%d, want %d", runID, state, count, want)
	}
}

