	t.Helper()
	deliveries := readServedForkDeliveryEvidence(t, rt, runID)
	matched := 0
	for id, delivery := range deliveries {
		if delivery.eventID != eventID {
			continue
		}
		matched++
		logServedForkWorkflowRows(t, rt, runID)
