						t.Fatalf("live evidence fault affected %d rows: %v", n, err)
					}
					var mutated []byte
					if err := rt.DB.QueryRow(`SELECT payload_bytes FROM events WHERE event_id=$1`, point.EventID).Scan(&mutated); err != nil {
						t.Fatal(err)
					}
