	requireServedJSONRPCResult(t, firstURL+"/v1/rpc", "event.get", map[string]any{"event_id": publication.EventIDs[1]}, &normalized)
	if normalized.RunID != binding.RunID || normalized.EntityID == "" || len(normalized.Deliveries) != 1 || normalized.Deliveries[0].Target.EntityID != normalized.EntityID {
		t.Fatalf("mock receiver readback lost exact delivery target: %+v", normalized)
	}
	entityID := normalized.EntityID
	cardID := waitForMockConnectorDecisionCard(t, backend, location, 1)
	assertMockMailboxReadback(t, firstURL+"/v1/rpc", cardID)
	approveMockDecisionCard(t, firstURL+"/v1/rpc", cardID)
	waitForMockConnectorAttempts(t, backend, location, 1)
	if code := first.stop(); code != 0 {
		t.Fatalf("first serve exit = %d\n%s", code, first.outputString())
	}
	before := loadStandingMemorySessions(t, backend, location)
	requireMockSessionShape(t, before)
	if prepareRestart != nil {
		prepareRestart()
	}
	second := startOwnedMockLifecycleTestProcess(t, repoRootForTest(), retainedRoot, opts)
	second.waitForReadyLine()
	secondURL := "http://" + serveRuntimeAPIListenerFromOutput(t, second.outputString())
	waitForMockConnectorAttempts(t, backend, location, 1)
	if got := sendStandingTelegramUpdate(t, secondURL, 302, 42); got != binding {
		t.Fatalf("post-restart binding = %+v, want %+v", got, binding)
	}
	waitForMockAgentTurns(t, backend, location, 2)
	secondCardID := waitForMockConnectorDecisionCard(t, backend, location, 2)
	approveMockDecisionCard(t, secondURL+"/v1/rpc", secondCardID)
	waitForMockConnectorAttempts(t, backend, location, 2)
	assertMockUsageReadback(t, secondURL+"/v1/rpc", mockSessionRunID(t, before), "phrase-bot")
	t.Run("effective_frame_exact_source", func(t *testing.T) {
		artifact, err := sourceartifact.AdmitDirectory(sourceRoot)
		if err != nil {
			t.Fatal(err)
		}
		for _, session := range before {
			if session.AgentID != "phrase-bot" {
				continue
			}
			args := []string{"agent", "frame", session.AgentID, "--run-id", session.RunID, "--flow-instance", session.FlowInstance, "--api-server", secondURL}
			for _, machine := range []bool{false, true} {
				var out, errOut bytes.Buffer
				command := append([]string(nil), args...)
				if machine {
					command = append(command, "--json")
				}
				if code := executeCLIFrom(context.Background(), t.TempDir(), command, &out, &errOut, nil); code != 0 {
					t.Fatalf("effective frame=%d %s / %s", code, &out, &errOut)
				}
				if machine {
					var frame agentframe.Inspection
					if err := json.Unmarshal(out.Bytes(), &frame); err != nil || frame.Session.BundleHash != artifact.BundleHash() || frame.SourceLabel != artifact.HumanLabel() || frame.Scope != agentframe.InspectionEffective {
						t.Fatalf("effective frame lost exact source: %s / %v", &out, err)
					}
				} else if !strings.Contains(out.String(), artifact.HumanLabel()) || strings.Contains(out.String(), artifact.BundleHash()) {
					t.Fatalf("human frame confused presentation with machine authority: %s", &out)
				}
			}
			return
		}
		t.Fatal("real mock session has no phrase-bot frame")
	})
	if code := second.stop(); code != 0 {
		t.Fatalf("second serve exit = %d\n%s", code, second.outputString())
	}
	after := loadStandingMemorySessions(t, backend, location)
	assertMockSessionContinuity(t, before, after)
	assertMockSupportedEvidence(t, backend, location, entityID)
	return time.Since(servedPathStarted)
}

