				if err != nil {
					t.Fatal(err)
				}
				plans, err := store.GeneratePlatformTableDDLs(spec)
				if err != nil {
					t.Fatal(err)
				}
				if err := artifacts.BootstrapSchema(ctx, store.SchemaBootstrapRequest{PlatformPlans: plans, Origin: store.RuntimeStoreOrigin{SwarmVersion: "startup-integrity-test", PlatformVersion: "test", CreatedAt: time.Now().UTC()}}); err != nil {
					t.Fatal(err)
				}
				root := t.TempDir()
				if err := os.WriteFile(filepath.Join(root, "schema.yaml"), []byte("name: historical-source\n"), 0o600); err != nil {
					t.Fatal(err)
				}
				artifact, err := sourceartifact.AdmitDirectory(root)
				if err != nil {
					t.Fatal(err)
				}
				if _, err := artifacts.EnsureSourceArtifact(ctx, artifact); err != nil {
					t.Fatal(err)
				}
