						var count int
						if err := proof.DB.QueryRow("SELECT COUNT(*) FROM "+table+" WHERE run_id = $1", initial.RunID).Scan(&count); err != nil || count != 0 {
							t.Fatalf("cleared reset retained %s: count=%d err=%v", table, count, err)
						}
					}
				}
			})
