	provider := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		providerCalls.Add(1)
		http.Error(w, "generated input proof must not call provider transport", http.StatusInternalServerError)
	}))
	t.Cleanup(provider.Close)
	sourceRoot := writeGeneratedTelegramScenarioFixture(t, provider.URL)
	var db *sql.DB
	var configPath string
	var runtimeContexts *runtimepkg.RuntimeContextManager
	opts := cliapp.ServeOptions{SourceRoot: sourceRoot, PlatformSpecPath: defaultPlatformSpecPath, APIListenAddr: "127.0.0.1:0", MCPListenAddr: "127.0.0.1:0", SelfCheck: true, Verbose: true, TestOutboxSweeperConfig: servedEventPublishProofOutboxSweeperConfig(), TestRuntimeContextsReadyHook: func(manager *runtimepkg.RuntimeContextManager) {
		runtimeContexts = manager
	}}
