	h.opts.AbandonActiveRuns = false
	if activityCredential != "" {
		credentials, err := runtimecredentials.NewFileStore(h.credentialPath)
		if err != nil {
			t.Fatal(err)
		}
		if err := credentials.Set(context.Background(), "mock_api_key", activityCredential); err != nil {
			t.Fatal(err)
		}
	}
	h.start(t)
	t.Cleanup(func() {
		h.stop(t)
	})
	driver := "sqlite"
	if backend == servedparity.BackendExplicitPostgres {
		driver = "postgres"
	}
	db, err := sql.Open(driver, h.storeDSN)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		_ = db.Close()
	})
	var begun channelonboarding.Result
	requireServedJSONRPCResult(t, h.rpcEndpoint(), "channel.onboarding_start", map[string]any{"provider": "mock", "verb": "connect", "provider_credential": "object-provider-secret", "save_proof": true, "client_language": "fr"}, &begun)
