					t.Fatal(err)
				}
				if _, err := rt.DB.Exec(`CREATE TRIGGER audit2277_completion BEFORE INSERT ON api_idempotency FOR EACH ROW WHEN (NEW.method='run.fork') EXECUTE FUNCTION audit2277_completion_failure()`); err != nil {
