			for _, check := range []struct {
				query string
				into  *int
			}{{`SELECT COUNT(*) FROM fan_out_outcomes WHERE run_id=$1`, &outcomeCount}, {`SELECT COUNT(*) FROM events WHERE run_id=$1 AND event_name='root.ready'`, &eventCount}, {`SELECT COUNT(*) FROM event_deliveries WHERE run_id=$1`, &deliveryCount}, {`SELECT COUNT(*) FROM event_deliveries WHERE run_id=$1 AND status='delivered'`, &settledCount}, {`SELECT COUNT(*) FROM event_deliveries WHERE run_id=$1 AND continuation_handoff_at IS NOT NULL`, &handoffCount}, {`SELECT COUNT(*) FROM event_receipts r JOIN events e ON e.event_id=r.event_id WHERE e.run_id=$1 AND r.subscriber_type='platform' AND r.subscriber_id='pipeline' AND r.outcome='success'`, &receiptCount}} {
				if err := f.db.QueryRowContext(f.ctx, check.query, runID).Scan(check.into); err != nil {
					t.Fatal(err)
				}
			}
			if outcomeCount != 2 || eventCount != 2 || deliveryCount != 2 || settledCount != 2 || handoffCount != 2 || receiptCount != 2 {
