				process, selected := start()
				before := lifecycleAdmissionDomainCounts(t, selected.DB)
				var sourcesBefore int
				if err := selected.DB.QueryRow("SELECT COUNT(*) FROM source_artifacts").Scan(&sourcesBefore); err != nil {
					t.Fatal(err)
				}
